localStorage.getItem("color-theme")==="dark"||!("color-theme"in localStorage)&&window.matchMedia("(prefers-color-scheme: dark)").matches?document.documentElement.classList.add("dark"):document.documentElement.classList.remove("dark");function updateIcons(){document.documentElement.classList.contains("dark")?(document.getElementById("theme-toggle-dark-icon").classList.add("hidden"),document.getElementById("theme-toggle-light-icon").classList.remove("hidden")):(document.getElementById("theme-toggle-dark-icon").classList.remove("hidden"),document.getElementById("theme-toggle-light-icon").classList.add("hidden"))}document.addEventListener("DOMContentLoaded",updateIcons),document.getElementById("theme-toggle").addEventListener("click",function(){document.documentElement.classList.toggle("dark"),document.documentElement.classList.contains("dark")?localStorage.setItem("color-theme","dark"):localStorage.setItem("color-theme","light"),updateIcons()})